// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(bytes32 role, address caller, address confirmation) public {
        vm.assume(caller != address(0));
        vm.assume(confirmation != address(0));

        bool ok;
        vm.prank(caller);
        try c.renounceRole(role, confirmation) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: renouncing `role` for `confirmation` succeeds exactly when
        // the caller confirms their own address (confirmation == caller). The bug
        // inverts the check, so it reverts when they match and succeeds otherwise.
        assertTrue(ok == (confirmation == caller));
    }
}
